Menulis permainan ular (Snake Game) dalam bahasa C yang *lancar* dan menggunakan **imej untuk menganimasikan seluruh peringkat** memerlukan gabungan beberapa komponen:

1. **Bahasa C** – sebagai asas pengaturcaraan.
2. **Pustaka grafik** – untuk memaparkan imej dan antara muka grafik (GUI).
3. **Sokongan fail imej (PNG/JPG)** – untuk memuat dan mempamerkan imej.
4. **Animasi dan kemas kini berterusan** – agar permainan kelihatan lancar.

### Pilihan Terbaik: Menggunakan **SDL2 (Simple DirectMedia Layer)**

SDL2 adalah pustaka C yang sangat sesuai untuk permainan 2D. Ia menyokong:

- Tetingkap dan input (papan kekunci, tetikus)
- Pemaparan grafik (termasuk imej PNG, JPG)
- Animasi berkelajuan tinggi
- Pemasa dan kemas kini berterusan

---

## ✅ Langkah 1: Pasang SDL2

Pastikan anda memasang SDL2 dan SDL2_image (untuk sokongan imej).

### Di Linux (Ubuntu/Debian):
```bash
sudo apt install libsdl2-dev libsdl2-image-dev
```

### Di Windows:
- Muat turun dari [https://www.libsdl.org](https://www.libsdl.org)
- Gunakan MinGW atau Visual Studio
- Atau gunakan MSYS2: `pacman -S mingw-w64-x86_64-SDL2 mingw-w64-x86_64-SDL2_image`

### Di macOS:
```bash
brew install sdl2 sdl2_image
```

---

## ✅ Langkah 2: Struktur Projek

Anda perlukan:
- Fail sumber C: `snake.c`
- Imej untuk ular, makanan, latar belakang (e.g., `head.png`, `body.png`, `food.png`, `bg.jpg`)
- Kompilasi dengan pustaka SDL2

---

## ✅ Kod Contoh: Permainan Ular dengan Imej (Menggunakan SDL2)

```c
// snake.c - Permainan Ular dengan Imej menggunakan SDL2
#include <SDL2/SDL.h>
#include <SDL2/IMG.h>
#include <stdio.h>
#include <stdlib.h>

#define SCREEN_WIDTH 800
#define SCREEN_HEIGHT 600
#define BLOCK_SIZE 32  // Saiz setiap blok (imej 32x32 px)
#define MAX_SEGMENTS 1000

// Struktur untuk ular
typedef struct {
    int x, y;
} Segment;

typedef struct {
    Segment body[MAX_SEGMENTS];
    int length;
    int dx, dy;  // arah
} Snake;

// Struktur untuk makanan
typedef struct {
    int x, y;
} Food;

// Fungsi untuk muat imej
SDL_Texture* loadTexture(const char* path, SDL_Renderer* renderer) {
    SDL_Surface* loadedSurface = IMG_Load(path);
    if (!loadedSurface) {
        printf("Tidak boleh muat imej %s! SDL_image Error: %s\n", path, IMG_GetError());
        return NULL;
    }

    SDL_Texture* texture = SDL_CreateTextureFromSurface(renderer, loadedSurface);
    SDL_FreeSurface(loadedSurface);
    return texture;
}

// Fungsi reset permainan
void initSnake(Snake* snake) {
    snake->length = 3;
    snake->dx = 1;
    snake->dy = 0;
    for (int i = 0; i < snake->length; i++) {
        snake->body[i].x = 5 - i;
        snake->body[i].y = 5;
    }
}

void initFood(Food* food, Snake* snake) {
    // Letakkan makanan secara rawak, jangan pada badan ular
    do {
        food->x = rand() % (SCREEN_WIDTH / BLOCK_SIZE);
        food->y = rand() % (SCREEN_HEIGHT / BLOCK_SIZE);
    } while (0); // tambah logik jika mahu elak badan ular
}

int checkCollision(Snake* snake) {
    Segment head = snake->body[0];
    // Langgar dinding
    if (head.x < 0 || head.x >= SCREEN_WIDTH / BLOCK_SIZE ||
        head.y < 0 || head.y >= SCREEN_HEIGHT / BLOCK_SIZE)
        return 1;

    // Langgar badan
    for (int i = 1; i < snake->length; i++) {
        if (head.x == snake->body[i].x && head.y == snake->body[i].y)
            return 1;
    }
    return 0;
}

int main(int argc, char* argv[]) {
    // Inisialisasi SDL
    if (SDL_Init(SDL_INIT_VIDEO) < 0) {
        printf("SDL tidak boleh dimulakan! SDL Error: %s\n", SDL_GetError());
        return 1;
    }

    // Buat tetingkap
    SDL_Window* window = SDL_CreateWindow("Permainan Ular", SDL_WINDOWPOS_CENTERED,
                                          SDL_WINDOWPOS_CENTERED, SCREEN_WIDTH, SCREEN_HEIGHT, 0);
    if (!window) {
        printf("Tetingkap gagal dicipta! SDL Error: %s\n", SDL_GetError());
        SDL_Quit();
        return 1;
    }

    SDL_Renderer* renderer = SDL_CreateRenderer(window, -1, SDL_RENDERER_ACCELERATED);
    if (!renderer) {
        printf("Renderer gagal dicipta! SDL Error: %s\n", SDL_GetError());
        SDL_DestroyWindow(window);
        SDL_Quit();
        return 1;
    }

    // Muat imej
    SDL_Texture* bgTexture = loadTexture("bg.jpg", renderer);
    SDL_Texture* headTexture = loadTexture("head.png", renderer);
    SDL_Texture* bodyTexture = loadTexture("body.png", renderer);
    SDL_Texture* foodTexture = loadTexture("food.png", renderer);

    if (!bgTexture || !headTexture || !bodyTexture || !foodTexture) {
        printf("Gagal memuatkan salah satu imej!\n");
        return 1;
    }

    // Inisialisasi RNG dan objek permainan
    srand(SDL_GetTicks());
    Snake snake;
    Food food;
    initSnake(&snake);
    initFood(&food, &snake);

    int isRunning = 1;
    SDL_Event event;
    Uint32 lastUpdate = 0;
    const Uint32 moveDelay = 150; // ms antara pergerakan

    while (isRunning) {
        Uint32 currentTime = SDL_GetTicks();

        // Tangani input
        while (SDL_PollEvent(&event)) {
            if (event.type == SDL_QUIT) {
                isRunning = 0;
            }
            if (event.type == SDL_KEYDOWN) {
                switch (event.key.keysym.sym) {
                    case SDLK_UP: if (snake.dy == 0) { snake.dx = 0; snake.dy = -1; } break;
                    case SDLK_DOWN: if (snake.dy == 0) { snake.dx = 0; snake.dy = 1; } break;
                    case SDLK_LEFT: if (snake.dx == 0) { snake.dx = -1; snake.dy = 0; } break;
                    case SDLK_RIGHT: if (snake.dx == 0) { snake.dx = 1; snake.dy = 0; } break;
                    case SDLK_r: initSnake(&snake); initFood(&food, &snake); break;
                }
            }
        }

        // Kemas kini logik setiap 'moveDelay' ms
        if (currentTime - lastUpdate > moveDelay) {
            // Geser badan dari belakang
            for (int i = snake.length - 1; i > 0; i--) {
                snake.body[i] = snake.body[i - 1];
            }

            // Gerakkan kepala
            snake.body[0].x += snake.dx;
            snake.body[0].y += snake.dy;

            // Semak langgar
            if (checkCollision(&snake)) {
                printf("Permainan Tamat! Tekan R untuk cuba lagi.\n");
                SDL_Delay(500);
            }

            // Semak makan makanan
            if (snake.body[0].x == food.x && snake.body[0].y == food.y) {
                snake.length++;
                initFood(&food, &snake);
            }

            lastUpdate = currentTime;
        }

        // Render
        SDL_RenderClear(renderer);

        // Gambar latar belakang
        SDL_Rect bgRect = {0, 0, SCREEN_WIDTH, SCREEN_HEIGHT};
        SDL_RenderCopy(renderer, bgTexture, NULL, &bgRect);

        // Gambar makanan
        SDL_Rect foodRect = {food.x * BLOCK_SIZE, food.y * BLOCK_SIZE, BLOCK_SIZE, BLOCK_SIZE};
        SDL_RenderCopy(renderer, foodTexture, NULL, &foodRect);

        // Gambar ular
        for (int i = 0; i < snake.length; i++) {
            SDL_Texture* tex = (i == 0) ? headTexture : bodyTexture;
            SDL_Rect rect = {snake.body[i].x * BLOCK_SIZE, snake.body[i].y * BLOCK_SIZE, BLOCK_SIZE, BLOCK_SIZE};
            SDL_RenderCopy(renderer, tex, NULL, &rect);
        }

        SDL_RenderPresent(renderer);
    }

    // Bersihkan
    SDL_DestroyTexture(bgTexture);
    SDL_DestroyTexture(headTexture);
    SDL_DestroyTexture(bodyTexture);
    SDL_DestroyTexture(foodTexture);
    SDL_DestroyRenderer(renderer);
    SDL_DestroyWindow(window);
    IMG_Quit();
    SDL_Quit();

    return 0;
}
```

---

## ✅ Arahan Kompilasi

### Di Linux/macOS:
```bash
gcc snake.c -o snake -lSDL2 -lSDL2_image
./snake
```

### Di Windows (dengan MinGW):
```bash
gcc snake.c -o snake.exe -lSDL2 -lSDL2_image -mwindows
```

Pastikan fail `.dll` SDL2 berada dalam direktori yang sama (untuk Windows).

---

## ✅ Arahan Fail Imej

Letakkan imej dengan nama:

- `bg.jpg` – latar belakang permainan
- `head.png` – kepala ular (32x32)
- `body.png` – bahagian badan ular
- `food.png` – makanan (e.g., epal)

Anda boleh muat turun imej kecil dari laman seperti:
- [https://www.kenney.nl](https://www.kenney.nl) (aset permainan percuma)
- Gunakan GIMP atau Photoshop untuk potong imej 32x32 px.

---

## ✅ Ciri Tambahan (Opsional)

- Putar kepala ikut arah (gunakan `SDL_RenderCopyEx` dengan sudut)
- Bunyi menggunakan `SDL_mixer`
- Skor dan paparan UI
- Animasi makanan berkelip

---

## ✅ Kesimpulan

Dengan menggunakan **SDL2 + SDL2_image**, anda boleh:

✅ Buat permainan ular dalam C  
✅ Gunakan imej untuk ular, makanan, dan latar belakang  
✅ Hasilkan animasi lancar dengan kemas kini berkala  
✅ Paparkan antara muka grafik yang menarik

